window.docContents[75].resolve({"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Homomorphism-of-algebras/#Chapter2___Definition2___2___6___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.2. Algebras\u0009Homomorphism of algebras\u0009Homomorphism of algebras","header":"Formalization","id":"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Homomorphism-of-algebras/#Chapter2___Definition2___2___6___formalization"},"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Subrepresentation-of-a-quiver-representation/#Chapter2___Definition2___8___8___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.8. Quivers\u0009Subrepresentation of a quiver representation\u0009Subrepresentation of a quiver representation","header":"Formalization","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Subrepresentation-of-a-quiver-representation/#Chapter2___Definition2___8___8___formalization"},"/3___-General-results-of-representation-theory/3___10___-Representations-of-tensor-products/Failure-of-Theorem-3___10___2-for-infinite-dimensional-representations/#Introduction-to-Representation-Theory--3___-General-results-of-representation-theory--3___10___-Representations-of-tensor-products--Failure-of-Theorem-3___10___2-for-infinite-dimensional-representations":{"contents":"\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.10. Representations of tensor products","header":"Failure of Theorem 3.10.2 for infinite dimensional representations","id":"/3___-General-results-of-representation-theory/3___10___-Representations-of-tensor-products/Failure-of-Theorem-3___10___2-for-infinite-dimensional-representations/#Introduction-to-Representation-Theory--3___-General-results-of-representation-theory--3___10___-Representations-of-tensor-products--Failure-of-Theorem-3___10___2-for-infinite-dimensional-representations"},"/4___-Representations-of-finite-groups___-Basic-results/4___7___-Orthogonality-of-matrix-elements/Section-4___7___-Orthogonality-of-matrix-elements/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___7___-Orthogonality-of-matrix-elements--Section-4___7___-Orthogonality-of-matrix-elements":{"contents":"\n\n","context":"Introduction to Representation Theory\u00094. Representations of finite groups: Basic results\u00094.7. Orthogonality of matrix elements","header":"Section 4.7: Orthogonality of matrix elements","id":"/4___-Representations-of-finite-groups___-Basic-results/4___7___-Orthogonality-of-matrix-elements/Section-4___7___-Orthogonality-of-matrix-elements/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___7___-Orthogonality-of-matrix-elements--Section-4___7___-Orthogonality-of-matrix-elements"},"/5___-Representations-of-finite-groups___-Further-results/5___15___-The-Frobenius-character-formula/Cauchy-determinant-identity/#Chapter5___Lemma5___15___3":{"contents":"Lemma 5.15.3.\n\n\\frac{\\prod_{i<j}(z_j - z_i)(y_i - y_j)}{\\prod_{i,j}(z_i - y_j)} = \\det\\left(\\frac{1}{z_i - y_j}\\right).\n\nProof. Multiply both sides by \\prod_{i,j}(z_i - y_j). Then the right-hand side must vanish on the hyperplanes z_i = z_j and y_i = y_j (i.e., must be divisible by \\Delta(z)\\Delta(y)) and is a homogeneous polynomial of degree\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.15. The Frobenius character formula\u0009Cauchy determinant identity","header":"Cauchy determinant identity","id":"/5___-Representations-of-finite-groups___-Further-results/5___15___-The-Frobenius-character-formula/Cauchy-determinant-identity/#Chapter5___Lemma5___15___3"},"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Introduction-to-the-Frobenius-Schur-indicator/#Chapter5___Introduction___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.1. Frobenius-Schur indicator\u0009Introduction to the Frobenius-Schur indicator\u0009Introduction to the Frobenius-Schur indicator","header":"Formalization","id":"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Introduction-to-the-Frobenius-Schur-indicator/#Chapter5___Introduction___formalization"},"/5___-Representations-of-finite-groups___-Further-results/5___20___-Historical-interlude___-Hermann-Weyl-at-the-intersection-of-limitation-and-freedom/#chapter-05___section-5-20":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results","header":"5.20. Historical interlude: Hermann Weyl at the intersection of limitation and freedom","id":"/5___-Representations-of-finite-groups___-Further-results/5___20___-Historical-interlude___-Hermann-Weyl-at-the-intersection-of-limitation-and-freedom/#chapter-05___section-5-20"},"/5___-Representations-of-finite-groups___-Further-results/5___23___-Algebraic-representations-of-___GL_LPAR_V_RPAR____/Extension-to-sl_LPAR_V_RPAR_-and-SL_LPAR_V_RPAR__SEMI_-recovery-of-sl_LPAR_2_RPAR_-representation-theory/#Chapter5___Remark5___23___3":{"contents":"Remark 5.23.3. Since the Lie algebra \\mathfrak{sl}(V) of traceless operators on V is a quotient of \\mathfrak{gl}(V) by scalars, the above results extend in a straightforward manner to representations of the Lie algebra \\mathfrak{sl}(V). Similarly, the results for GL(V) extend to the case of the group SL(V) of operators with determinant 1. The only difference is that in this case the representations L_\\lambda and L_{\\lambda + 1^m} are isomorphic, so the irreducible representations are parametrized by integer sequences \\lambda_1 \\geq \\cdots \\geq \\lambda_N up to a simultaneous shift by a constant.\n\nIn particular, one can show that any finite dimensional representation of \\mathfrak{sl}(V) is completely reducible and any irreducible representation is of the form L_\\lambda (we will not do this here). For \\dim V = 2 one then recovers the representation theory of \\mathfrak{sl}(2) studied in Problem 2.15.1.\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.23. Algebraic representations of $GL(V)$\u0009Extension to sl(V) and SL(V); recovery of sl(2) representation theory","header":"Extension to sl(V) and SL(V); recovery of sl(2) representation theory","id":"/5___-Representations-of-finite-groups___-Further-results/5___23___-Algebraic-representations-of-___GL_LPAR_V_RPAR____/Extension-to-sl_LPAR_V_RPAR_-and-SL_LPAR_V_RPAR__SEMI_-recovery-of-sl_LPAR_2_RPAR_-representation-theory/#Chapter5___Remark5___23___3"},"/5___-Representations-of-finite-groups___-Further-results/5___24___-Problems/V____lambda-___-V_lambda-and-V_lambda-___-C_--___-V____lambda______/#Chapter5___Problem5___24___1":{"contents":"Problem 5.24.1. (a) Show that the S_n-representation\n\nV'_\\lambda := \\mathbb{C}[S_n] b_\\lambda a_\\lambda\n\nis isomorphic to V_\\lambda.\n\nHint: Define S_n-homomorphisms f : V_\\lambda \\to V'_\\lambda and g : V'_\\lambda \\to V_\\lambda by the formulas f(x) = x a_\\lambda and g(y) = y b_\\lambda, and show that they are inverse to each other up to a nonzero scalar.\n\n(b) Let \\phi : \\mathbb{C}[S_n] \\to \\mathbb{C}[S_n] be the automorphism sending s to (-1)^s s for any permutation s. Show that \\phi maps any representation V of S_n to V \\otimes \\mathbb{C}_-. Show also that \\phi(\\mathbb{C}[S_n] a) = \\mathbb{C}[S_n] \\phi(a), for a \\in \\mathbb{C}[S_n]. Use (a) to deduce that V_\\lambda \\otimes \\mathbb{C}_- = V_{\\lambda^*}, where \\lambda^* is the conjugate partition to \\lambda, obtained by reflecting the Young diagram of \\lambda.\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.24. Problems\u0009V'_lambda ≅ V_lambda and V_lambda ⊗ C_- = V_{lambda*}","header":"V'_lambda ≅ V_lambda and V_lambda ⊗ C_- = V_{lambda*}","id":"/5___-Representations-of-finite-groups___-Further-results/5___24___-Problems/V____lambda-___-V_lambda-and-V_lambda-___-C_--___-V____lambda______/#Chapter5___Problem5___24___1"},"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/5___25___4___-Complementary-series/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____--5___25___4___-Complementary-series--Summary___-all-q___2-1-irreducible-representations-of-GL_2_LPAR_F_q_RPAR_-found--Summary___-all-q___2-1-irreducible-representations-of-GL_2_LPAR_F_q_RPAR_-found--Formalization--Supporting-declarations":{"contents":"The number of conjugacy classes is one less than the square of the finite-field cardinality when the characteristic is not two and the extension degree is nonzero.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_5.25.1; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary/Derived01; role=supporting]\n\nAn auxiliary finite-dimensional complex representation indexed by the auxiliary type.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary/Derived01; role=supporting]\n\nIsomorphic representations in the indexed family have equal indices.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary/Derived01; role=supporting]\n\nEvery representation in the indexed family is simple.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary/Derived01; role=supporting]\n\nComputes the cardinality of the auxiliary index type.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary/Derived01; role=supporting]\n\nComputes the number of conjugacy classes of the two-dimensional general linear group.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]\n\nA supplied conjugacy-class count equals the displayed auxiliary expression.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]\n\nEvery simple representation is isomorphic to a unique member of the indexed family.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary/Derived01; role=supporting]\n\nThere exists a type with cardinality one less than the square of the field cardinality.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]\n\nThere exists a complete pairwise nonisomorphic family of simple representations of the stated size.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]\n\nThere is a matrix-algebra decomposition indexed by a type of the displayed cardinality.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]\n\nThe finite field satisfies the auxiliary property under the displayed assumptions.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]\n\nA suitably sized pairwise nonisomorphic simple family contains every simple representation up to isomorphism.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary; role=supporting]\n\nExpresses q^2 - 1 as q - 1 plus twice a quotient.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_complementary_series_summary/Derived01; role=supporting]\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.25. Representations of $GL_2(\\mathbb{F}_q)$\u00095.25.4. Complementary series\u0009Summary: all q^2-1 irreducible representations of GL_2(F_q) found\u0009Summary: all q^2-1 irreducible representations of GL_2(F_q) found\u0009Formalization","header":"Supporting declarations","id":"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/5___25___4___-Complementary-series/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____--5___25___4___-Complementary-series--Summary___-all-q___2-1-irreducible-representations-of-GL_2_LPAR_F_q_RPAR_-found--Summary___-all-q___2-1-irreducible-representations-of-GL_2_LPAR_F_q_RPAR_-found--Formalization--Supporting-declarations"},"/6___-Quiver-representations/6___4___-Roots/Definition-6___4___3___-Root/#Chapter6___Definition6___4___3":{"contents":"Definition 6.4.3. A root with respect to a certain positive inner product is a shortest (with respect to this inner product) nonzero vector in \\mathbb{Z}^n.\n\nSo for the inner product B, a root is a nonzero vector x \\in \\mathbb{Z}^n such that\n\nB(x, x) = 2.\n\n\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.4. Roots\u0009Definition 6.4.3: Root","header":"Definition 6.4.3: Root","id":"/6___-Quiver-representations/6___4___-Roots/Definition-6___4___3___-Root/#Chapter6___Definition6___4___3"},"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Corollary-6___8___3___-Uniqueness-of-indecomposable-with-given-dimension-vector/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___8___-Proof-of-Gabriel___s-theorem--Corollary-6___8___3___-Uniqueness-of-indecomposable-with-given-dimension-vector--Corollary-6___8___3___-Uniqueness-of-indecomposable-with-given-dimension-vector--Formalization--Primary-declarations":{"contents":"Under the displayed matrix and quiver hypotheses, two auxiliary representations with matching vertexwise dimensions admit an auxiliary relation.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter6/Corollary6.8.3; role=primary]\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.8. Proof of Gabriel's theorem\u0009Corollary 6.8.3: Uniqueness of indecomposable with given dimension vector\u0009Corollary 6.8.3: Uniqueness of indecomposable with given dimension vector\u0009Formalization","header":"Primary declarations","id":"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Corollary-6___8___3___-Uniqueness-of-indecomposable-with-given-dimension-vector/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___8___-Proof-of-Gabriel___s-theorem--Corollary-6___8___3___-Uniqueness-of-indecomposable-with-given-dimension-vector--Corollary-6___8___3___-Uniqueness-of-indecomposable-with-given-dimension-vector--Formalization--Primary-declarations"},"/6___-Quiver-representations/6___9___-Problems/Section-6___9-heading___-Problems/#Chapter6___Section6___9_heading":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.9. Problems\u0009Section 6.9 heading: Problems","header":"Section 6.9 heading: Problems","id":"/6___-Quiver-representations/6___9___-Problems/Section-6___9-heading___-Problems/#Chapter6___Section6___9_heading"},"/7___-Introduction-to-categories/7___4___-Equivalence-of-categories/Examples-of-equivalent-categories/#Chapter7___Discussion_after_Definition7___4___1":{"contents":"In particular, the above categories \\mathcal{C}_1 and \\mathcal{C}_2 are equivalent (check it!).\n\nAlso, the category FSet of finite sets is equivalent to the category whose objects are nonnegative integers, and morphisms are given by\n\n\\operatorname{Hom}(m, n) = \\operatorname{Maps}(\\{1, \\ldots, m\\}, \\{1, \\ldots, n\\}).\n\nAre these categories isomorphic? The answer to this question depends on whether you believe that there is only one finite set with a given number of elements, or that there are many of those. It seems better to think that there are many (without asking \"how many\"), so that isomorphic sets need not be literally equal, but this is really a matter of choice. In any case, this is not really a reasonable question; the answer to this question is irrelevant for any practical purpose, and thinking about it will give you nothing but a headache.\n\n\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.4. Equivalence of categories\u0009Examples of equivalent categories","header":"Examples of equivalent categories","id":"/7___-Introduction-to-categories/7___4___-Equivalence-of-categories/Examples-of-equivalent-categories/#Chapter7___Discussion_after_Definition7___4___1"},"/7___-Introduction-to-categories/7___8___-Complexes-and-cohomology/Split-exact-sequence/#Chapter7___Example7___8___3___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.8. Complexes and cohomology\u0009Split exact sequence\u0009Split exact sequence","header":"Formalization","id":"/7___-Introduction-to-categories/7___8___-Complexes-and-cohomology/Split-exact-sequence/#Chapter7___Example7___8___3___formalization"},"/7___-Introduction-to-categories/7___9___-Exact-functors/Ind___-Res___-Hom-as-additive-k-linear-functors/#Chapter7___Example7___9___2":{"contents":"Example 7.9.2. The functors \\operatorname{Ind}_K^G, \\operatorname{Res}_K^G, \\operatorname{Hom}_G(V, ?) in the theory of group representations over a field k are additive and k-linear.\n\n\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.9. Exact functors\u0009Ind, Res, Hom as additive k-linear functors","header":"Ind, Res, Hom as additive k-linear functors","id":"/7___-Introduction-to-categories/7___9___-Exact-functors/Ind___-Res___-Hom-as-additive-k-linear-functors/#Chapter7___Example7___9___2"},"/8___-Homological-algebra/8___1___-Projective-and-injective-modules/#chapter-08___section-8-1":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\u00098. Homological algebra","header":"8.1. Projective and injective modules","id":"/8___-Homological-algebra/8___1___-Projective-and-injective-modules/#chapter-08___section-8-1"}});